<div class="pixel-room" class:compact data-layout={panorama?'panorama':'table'} data-background-swapping={swapping} data-speaking={speaking} data-weather={weather} data-strength={drawnStrength.toFixed(2)} data-strength-target={strength.toFixed(2)} data-light={light} data-lamp={lampOn?'on':'off'} data-scene={scene} data-display-scene={displayedScene} data-window-art={windowArt} data-avatar={avatar} data-character="xiaoyu-original" onpointermove={pointerMove} onpointerleave={()=>{target={x:0,y:0};snowPointer=undefined;}} role="presentation">
