</div>
<style>
 .pixel-room{position:absolute;inset:0;overflow:hidden}.pixel-room canvas{width:100%;height:100%;display:block}.room-hotspot{position:absolute;background:transparent;border:0;cursor:pointer;border-radius:18px;touch-action:manipulation;outline:none!important;box-shadow:none}.room-hotspot:focus-visible::after{content:'';position:absolute;left:calc(50% - 5px);bottom:4px;width:10px;height:10px;transform:rotate(45deg);background:var(--xy-accent);border:2px solid var(--xy-panel);border-radius:2px}.room-hotspot.lamp{min-width:44px;min-height:44px}.room-hint{position:absolute;right:3%;bottom:12px;max-width:min(280px,85%);background:var(--xy-panel);border:1px solid var(--xy-border);padding:7px 11px;color:var(--xy-ink);border-radius:9px;font:12px/1.65 'Noto Sans SC','Microsoft YaHei',sans-serif;pointer-events:none}
